import{z as B,x as l,o as r,c as p,q as t,j as s,D as e,d as i,s as o,S as n}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"微观结构噪声","description":"","frontmatter":{"title":"微观结构噪声","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/microstructure-noise.md","filePath":"quant/microstructure-noise.md","lastUpdated":1791063341000}'),A={name:"quant/microstructure-noise.md"};function u(m,a,_,d,c,h){const E=l("Mermaid");return r(),p("div",null,[a[2]||(a[2]=t('<h1 id="微观结构噪声" tabindex="-1">微观结构噪声 <a class="header-anchor" href="#微观结构噪声" aria-label="Permalink to &quot;微观结构噪声&quot;">​</a></h1><div class="epigraph"><p>观测到的成交价等于有效价格加上一个暂时的定价误差；误差会反转，有效价格才是信息进入市场的那条鞅。</p><footer>—— Hasbrouck, Assessing the Quality of a Security Market: A New Approach to Transaction-Cost Measurement, Review of Financial Studies 1993</footer></div><p><a href="/quant/outlier-trades">上一课</a>把错价与错量的处置收成传给下游的数据契约；寻常观测里的噪声还在。把成交价当成有效价格的直接观测，高频统计会立刻坏掉：采样越密，<a href="/quant/rv-noise">已实现波动</a> 越大，收益出现负的一阶自相关，买卖之间像在弹跳。这些现象不是「市场越看越险」，而是观测值里有一层<strong>微观结构噪声</strong>——买卖价差、最小报价单位、存货、暂时流动性冲击。Roll 用价差弹跳解释收益协方差；Hasbrouck 把成交价拆成随机游走的有效价格与平稳的定价误差，用向量自回归估计误差方差，作为市场质量。本篇写噪声作为数据生成过程，以及它如何污染朴素统计量；如何从 RV 里把噪声抠掉，是下一篇的修正方法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记有效价格（信息充分反映后的证券价值）为 \\(X_t\\)，通常假定为半鞅。观测价格 \\(Y_t=X_t+\\varepsilon_t\\)。\\(\\varepsilon_t\\) 来自：成交发生在买或卖一侧（Roll 弹跳）、价格必须落在离散网格、做市商存货导致的暂时偏离、以及报告延迟。\\(\\varepsilon_t\\) 可以与 \\(X\\) 相关（信息不对称时，方向与后续 \\(X\\) 同向），也可以有自己的序列相关（同一侧连续成交）。</p><p>若假装 \\(\\varepsilon=0\\)，用很密的采样算 \\(\\sum (\\Delta Y)^2\\)，噪声的二次变差不会消失：i.i.d. 噪声下，这一项以采样次数的速度爆炸。若用日收益，噪声被日波动淹没，但又浪费了日内信息。问题是承认 \\(Y\\) 不是 \\(X\\)，再决定：哪些问题必须对 \\(X\\) 提问（波动、beta、信息份额），哪些问题本来就要对 \\(Y\\) 提问（成交价、执行成本）。</p><h3 id="roll-弹跳是噪声的最小模型" tabindex="-1">Roll 弹跳是噪声的最小模型 <a class="header-anchor" href="#roll-弹跳是噪声的最小模型" aria-label="Permalink to &quot;Roll 弹跳是噪声的最小模型&quot;">​</a></h3><p>Roll（1984）设有效价格随机游走，成交价在有效价格上加减半个价差：\\(Y_t=X_t+\\frac{s}{2}Q_t\\)，\\(Q_t=\\pm 1\\) 为买卖方向。若方向不相关，收益的一阶协方差 \\(\\mathrm{Cov}(\\Delta Y_t,\\Delta Y_{t-1})=-s^2/4\\)，从而 \\(\\hat s=2\\sqrt{-\\hat\\gamma_1}\\)。协方差一旦为正，公式崩溃——现实里信息与存货会让 \\(\\gamma_1\\) 变号。Roll 不是失败的价差估计那么简单，它说明：<strong>负自相关是噪声的指纹</strong>，但指纹会被信息涂改。</p><p><span class="marginnote">数字实例：若日收益一阶自协方差估出 \\(\\hat\\gamma_1=-0.0001\\)（元²），代入 \\(\\hat s=2\\sqrt{-\\hat\\gamma_1}\\) 得有效价差 0.02 元。反过来，每笔成交价都带着 \\(\\pm 0.01\\) 元的弹跳——这就是「负自相关是噪声指纹」的具体尺寸。</span></p><p><span class="marginnote">噪声不是测量仪器的电噪声，虽然录入错误也是一种 \\(\\varepsilon\\)。经济噪声有符号结构：主动买倾向于 \\(+\\varepsilon\\)，随后若无信息，\\(Y\\) 应回到 \\(X\\)。这就是实现价差会小于有效价差的微观基础。把 \\(\\varepsilon\\) 当成高斯白噪声，是为了写 RV 极限定理，不是对订单簿的完整描述。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>加性噪声的 RV 偏差。</strong> 在 \\([0,1]\\) 上 \\(n\\) 等分采样，\\(r_{i}=Y_{i/n}-Y_{(i-1)/n}\\)。若 \\(\\varepsilon\\) 为 i.i.d.、方差 \\(\\sigma_\\varepsilon^2\\)，与 \\(X\\) 独立，则</p> \\[\\mathbb{E}\\sum_{i=1}^{n} r_i^2 \\approx \\langle X\\rangle_1 + 2n\\sigma_\\varepsilon^2. \\]<p>真实积分波动被一项与 \\(n\\) 成正比的噪声主导。这解释了「越密越抖」的签名图（signature plot）：横轴采样频率，纵轴 RV，曲线在高频端上翘。</p><p><span class="marginnote">数字实例：噪声幅度 1 分钱、股价 20 元时 \\(\\sigma_\\varepsilon=0.0005\\)（相对值）。每 10 秒采样一次，一天约 \\(n=2340\\) 个增量，噪声贡献 \\(2n\\sigma_\\varepsilon^2\\approx 0.0012\\)；而日波动 1% 的股票真实积分方差只有 \\(0.0001\\)——高频端噪声把估计放大了十倍以上，采样越勤，错得越离谱。</span></p><p><strong>Hasbrouck 定价误差。</strong> 把中点或成交价的变动与订单流放进 VAR，把价格分解为随机游走（信息）与平稳成分（定价误差）。定价误差的方差衡量市场质量：越小，观测价越贴近有效价。信息份额（Hasbrouck 1995）在多市场同时交易同一证券时，把随机游走方差的贡献分给各市场——回答「价格发现在哪发生」，不是回答「噪声方差是多少」，但共用同一套有效价格 vs 误差的语言。</p><p><strong>相关噪声与内生时间。</strong> 真实 \\(\\varepsilon\\) 往往与交易强度、方向相关。等间隔日历采样会在交易稀少时重复同一个过时价格（零收益插值），制造额外的自相关。这把噪声问题与 <a href="/quant/irregular-sampling">不等间隔采样</a> 绑在一起：采样方案本身在制造 \\(\\varepsilon\\) 的表观结构。</p><h3 id="签名图作为诊断-而不是模型" tabindex="-1">签名图作为诊断，而不是模型 <a class="header-anchor" href="#签名图作为诊断-而不是模型" aria-label="Permalink to &quot;签名图作为诊断，而不是模型&quot;">​</a></h3><p>画不同 \\(\\Delta\\) 下的 RV\\((\\Delta)\\)，是确认噪声是否主导的第一步。若五分钟已经平坦、一分钟仍上翘，噪声在一分钟尺度可见。若全日都平坦，要么噪声极小，要么你的「成交」其实已被交易所聚合成分钟线。签名图不能给出 \\(\\sigma_\\varepsilon\\) 的无偏估计——那需要 <a href="/quant/rv-noise">两尺度 RV、核或预平均</a>——但它决定你有没有资格用朴素 RV。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>价差弹跳的机制是会计恒等式：一轮买上一轮卖，价格必须走一个来回，有效价值可以没动。离散报价的机制是圆整：有效价格在网格间连续移动时，观测值长时间不动，然后跳一个 tick，零收益与一跳交替，看起来像噪声。存货机制是暂时供给：做市商被卖单击中后降价吸引买家，价格偏离 \\(X\\)，随后回归。信息不对称则让 \\(\\varepsilon\\) 与未来 \\(\\Delta X\\) 相关：主动买之后 \\(X\\) 上移，暂时成分与永久成分混在一笔 \\(\\Delta Y\\) 里。</p>',21)),(r(),s(n,null,{default:e(()=>[o(E,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOUNCE%5B%22%E4%BB%B7%E5%B7%AE%E5%BC%B9%E8%B7%B3%EF%BC%9A%E4%B9%B0%E5%8D%96%E4%BA%A4%E6%9B%BF%20%C2%B1s%2F2%22%5D%20--%3E%20SIG%5B%22%E5%90%84%E8%87%AA%E7%9A%84%E8%A7%82%E6%B5%8B%E7%AD%BE%E5%90%8D%22%5D%0A%20%20TICK%5B%22%E7%BD%91%E6%A0%BC%E5%9C%86%E6%95%B4%EF%BC%9A%E4%B8%8D%E5%8A%A8%E5%90%8E%E8%B7%B3%E4%B8%80%20tick%22%5D%20--%3E%20SIG%0A%20%20INV%5B%22%E5%AD%98%E8%B4%A7%EF%BC%9A%E8%A2%AB%E5%87%BB%E4%B8%AD%E5%90%8E%E9%99%8D%E4%BB%B7%E5%86%8D%E5%9B%9E%E5%BD%92%22%5D%20--%3E%20SIG%0A%20%20INFO%5B%22%E4%BF%A1%E6%81%AF%E4%B8%8D%E5%AF%B9%E7%A7%B0%EF%BC%9A%CE%B5%20%E4%B8%8E%E6%9C%AA%E6%9D%A5%20%CE%94X%20%E7%9B%B8%E5%85%B3%22%5D%20--%3E%20SIG%0A%20%20SIG%20--%3E%20S1%5B%22%E8%B4%9F%E4%B8%80%E9%98%B6%E8%87%AA%E7%9B%B8%E5%85%B3%EF%BC%88%E5%BC%B9%E8%B7%B3%E6%8C%87%E7%BA%B9%EF%BC%89%22%5D%0A%20%20SIG%20--%3E%20S2%5B%22%E9%9B%B6%E6%94%B6%E7%9B%8A%E4%B8%8E%E4%B8%80%E8%B7%B3%E4%BA%A4%E6%9B%BF%22%5D%0A%20%20SIG%20--%3E%20S3%5B%22%E6%9A%82%E6%97%B6%E5%81%8F%E7%A6%BB%E5%90%8E%E5%9B%9E%E5%BD%92%E6%88%96%E6%B0%B8%E4%B9%85%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20S1%20--%3E%20USE%5B%22%E5%86%B3%E5%AE%9A%E9%87%87%E6%A0%B7%E9%A2%91%E7%8E%87%E4%B8%8E%E4%BF%AE%E6%AD%A3%E6%96%B9%E6%B3%95%22%5D%0A%20%20S2%20--%3E%20USE%0A%20%20S3%20--%3E%20USE%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>Hasbrouck 的 VAR 机制是：用订单流与滞后收益去预测下一笔价格变化，把可预测的部分归为暂时，把新息的累积归为信息。识别依赖模型设定（包含哪些滞后、用成交还是中点）。它给出的误差方差是<strong>相对</strong>市场质量，不是 SI 单位下的物理噪声。</p><p><span class="marginnote">中点相对成交价更干净，因为买卖弹跳被平均掉一半；但中点不是可成交价格，且交叉报价、一档空洞会让中点乱跳。研究价格发现常用中点，研究执行成本必须用成交价。噪声的定义跟着你问的 \\(Y\\) 走。</span></p><h3 id="噪声与-pin-不是同一层" tabindex="-1">噪声与 PIN 不是同一层 <a class="header-anchor" href="#噪声与-pin-不是同一层" aria-label="Permalink to &quot;噪声与 PIN 不是同一层&quot;">​</a></h3><p><a href="/quant/pin">PIN</a> 描述知情到达如何改变买卖强度；噪声模型描述观测价如何偏离有效价。知情交易会同时抬高逆向选择（价差变宽、冲击变大）和改变 \\(\\varepsilon\\) 与 \\(X\\) 的相关。把 PIN 高读成「噪声大」是错的：PIN 高往往是永久冲击大，暂时噪声甚至可能因知情者少用中间价而改变形态。VPIN 的批量分类把价格变化当方向，等于把 \\(\\Delta Y\\)——含噪声——写进订单流，高频噪声会直接污染毒性指标。</p><p><span class="marginnote">术语翻译：PIN（知情交易概率）回答「跟我成交的对手里有多少是明白人」；微观结构噪声回答「我看到的价签离真实价值多远、会不会弹回来」。知情流变多时两者常同时变化，但一个在订单流层、一个在价格观测层，混为一谈会把毒性指标和执行质量搅在一起。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>加性 i.i.d. 噪声是为了写出 \\(2n\\sigma_\\varepsilon^2\\) 这一项。现实里噪声随波动、随深度、随会话变化，开盘的 \\(\\sigma_\\varepsilon\\) 大于午后。圆整是离散的，不是高斯。估计方法若假定独立噪声，在小 tick、高换手股票上偏差较小，在 tick 占波动很大的股票上偏差很大。</p><p>不要用收盘价的 Roll 估计去替代盘中有效价差：前者是日度协方差，后者是逐笔会计。不要把签名图上翘全部归因于买卖价差——<a href="/quant/outlier-trades">未清洗的错价</a> 会造成更猛的上翘。不要在噪声主导的频率上估 beta、相关、对冲比率，除非已经做噪声修正或降低采样频率。日历效应与隔夜跳变是另一层：隔夜 \\(\\Delta Y\\) 几乎没有买卖弹跳，却有信息，把隔夜和日内噪声当成同一种 \\(\\varepsilon\\) 会错。</p><p><span class="marginnote">Hasbrouck 的市场质量是定价误差方差，不是价差本身。价差可以宽但中点很接近有效价格（报价保守），也可以窄但中点被订单流推着暂时偏离。报告市场质量应同时给价差、冲击与定价误差，单看一个会把做市商的风险补偿和信息效率混在一起。</span></p>',9)),(r(),s(n,null,{default:e(()=>[o(E,{id:"mermaid-87",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%9C%89%E6%95%88%E4%BB%B7%E6%A0%BC%20X%20%E5%8D%8A%E9%9E%85%22%5D%20--%3E%20Y%5B%22%E8%A7%82%E6%B5%8B%E4%BB%B7%20Y%20%3D%20X%20%2B%20%CE%B5%22%5D%0A%20%20E%5B%22%E4%BB%B7%E5%B7%AE%E5%BC%B9%E8%B7%B3%20%2F%20%E5%9C%86%E6%95%B4%20%2F%20%E5%AD%98%E8%B4%A7%22%5D%20--%3E%20Y%0A%20%20Y%20--%3E%20RV%5B%22%E6%9C%B4%E7%B4%A0%20RV%3A%20%E2%9F%A8X%E2%9F%A9%20%2B%202n%20%CF%83%CE%B5%C2%B2%22%5D%0A%20%20Y%20--%3E%20AC%5B%22%E6%94%B6%E7%9B%8A%E8%B4%9F%E8%87%AA%E7%9B%B8%E5%85%B3%22%5D%0A%20%20Y%20--%3E%20VAR%5B%22Hasbrouck%20VAR%22%5D%0A%20%20VAR%20--%3E%20PE%5B%22%E5%AE%9A%E4%BB%B7%E8%AF%AF%E5%B7%AE%E6%96%B9%E5%B7%AE%22%5D%0A%20%20VAR%20--%3E%20IS%5B%22%E4%BF%A1%E6%81%AF%E4%BB%BD%E9%A2%9D%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>微观结构噪声是观测价相对有效价格的暂时偏差：弹跳、圆整、存货与延迟，不是仪器电噪声。</li><li>i.i.d. 加性噪声使朴素 RV 以 \\(2n\\sigma_\\varepsilon^2\\) 的速度膨胀，签名图在高频上翘是诊断。</li><li>Roll 协方差与 Hasbrouck 定价误差从两个方向刻画同一件事：暂时成分会反转，信息成分留下。</li><li>噪声与 PIN/价差冲击相关但不相同；采样方案本身会制造表观噪声。</li><li>问波动应对 \\(X\\)，问执行成本应对 \\(Y\\)；频率选在噪声尚未主导处，或进入 RV 修正。</li><li>出处：Hasbrouck, <em>Assessing the Quality of a Security Market</em>, Review of Financial Studies 1993；Roll, <em>A Simple Implicit Measure of the Effective Bid-Ask Spread</em>, Journal of Finance 1984。RV 极限中的噪声项见随后 Barndorff-Nielsen 与两尺度文献。</li></ul>',2))])}const f=B(A,[["render",u]]);export{g as __pageData,f as default};
